using UnityEngine;
using Zombera.Editor;
using Zombera.World.CityPipeline.WorldBuilder;

public static class HydroWaterVerify
{
    public static string Run()
    {
        var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
        if (scene.name != "1_World Generation")
            return "REFUSE scene=" + scene.name;

        Debug.Log("[HydroWaterVerify] starting TryRunHydrologyWaterVerifySync");
        if (!WorldBuilderHubPipelineRunner.TryRunHydrologyWaterVerifySync(out var error, 1800f))
            return "PIPELINE_FAIL: " + (error ?? "unknown");

        var service = Object.FindFirstObjectByType<WorldBuilderService>(FindObjectsInactive.Include);
        var hydro = service != null ? service.Artifacts?.Hydrology : null;
        if (hydro?.Rivers == null)
            return "NO_RIVERS after pipeline";

        var sb = new System.Text.StringBuilder();
        sb.Append("OK scene=").Append(scene.name);
        var best = 0f;
        var mouths = 0;
        var stems = 0;
        for (var i = 0; i < hydro.Rivers.Length; i++)
        {
            var r = hydro.Rivers[i];
            if (r == null) continue;
            if (r.Kind == RiverKind.MainStem) stems++;
            if (r.Kind != RiverKind.MainStem || !r.HasOceanMouth) continue;
            mouths++;
            var len = PolyLen(r.PointsXZ);
            if (len > best) best = len;
            sb.Append(" | stemId=").Append(r.StableId)
              .Append(" len=").Append(len.ToString("0"))
              .Append("m pts=").Append(r.PointsXZ != null ? r.PointsXZ.Length : 0);
        }

        var sys = 0;
        var transforms = Object.FindObjectsByType<Transform>(FindObjectsSortMode.None);
        for (var i = 0; i < transforms.Length; i++)
        {
            var t = transforms[i];
            if (t != null && t.name.StartsWith("RiverSystem_"))
            {
                sys++;
                sb.Append(" | GO=").Append(t.name);
            }
        }

        sb.Append(" || stems=").Append(stems)
          .Append(" oceanMouths=").Append(mouths)
          .Append(" bestLen=").Append(best.ToString("0"))
          .Append("m rivers=").Append(hydro.Rivers.Length)
          .Append(" RiverSystemGOs=").Append(sys)
          .Append(" meet3000=").Append(best >= 3000f);
        Debug.Log("[HydroWaterVerify] " + sb);
        return sb.ToString();
    }

    static float PolyLen(Vector2[] pts)
    {
        if (pts == null || pts.Length < 2) return 0f;
        var len = 0f;
        for (var i = 1; i < pts.Length; i++)
            len += Vector2.Distance(pts[i - 1], pts[i]);
        return len;
    }
}
